async page=>{
 const result={checks:[],errors:[],bad:[]},check=(name,ok,actual)=>{result.checks.push({name,ok,actual});if(!ok)throw Error(name+' '+JSON.stringify(actual))};
 page.on('pageerror',e=>result.errors.push(e.message));
 page.on('response',r=>{if(r.status()>=400&&r.url().includes('/Demo_Protype_2/'))result.bad.push(r.url())});
 await page.setViewportSize({width:1440,height:1050});
 await page.goto('http://127.0.0.1:8772/Demo_Protype_2/prototype/index.html');
 await page.evaluate(()=>{DemoSwitch.enter('ACC-SUPER-001');if(AppState.get().authStage==='INSTANCE')AppState.chooseInstance('7522240');if(AppState.get().authStage==='DOMAIN')AppState.chooseDomain('CLOUD_CONTACT_CENTER');RouteRuntime.openPrimary('tenants')});
 check('超级管理员就绪',await page.evaluate(()=>AppState.get().authStage==='READY'&&AppState.isSuper()));
 const inject=()=>page.evaluate(()=>{window.rg14OriginalSetItem=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k==='unified-call-demo-identities-v1')throw new DOMException('RG14 storage failure','QuotaExceededError');return window.rg14OriginalSetItem.call(this,k,v)}});
 const restore=()=>page.evaluate(()=>{Storage.prototype.setItem=window.rg14OriginalSetItem});
 const snapshot=()=>page.evaluate(()=>JSON.stringify({tenants:CloudCallData.tenants,accounts:CloudCallData.accounts,memberships:CloudCallData.memberships,instances:CloudCallData.instances,audits:CloudCallData.audits,stored:sessionStorage.getItem('unified-call-demo-identities-v1')}));
 const name='RG14租户'+Date.now();
 await page.evaluate(()=>AccountTenantForms.openTenant());
 await page.locator('#tenantName').fill(name);await page.locator('#tenantCCC').check();
 const before=await snapshot();await inject();
 await page.locator('#tenant-detail').getByRole('button',{name:'确定',exact:true}).click();
 check('新增租户失败时业务状态和存储未改变',(await snapshot())===before);
 check('新增租户失败保留表单输入',await page.locator('#tenantName').inputValue()===name&&await page.locator('#tenantNameError').innerText().then(t=>t.includes('保存失败')));
 await page.screenshot({path:'/private/tmp/rg14-tenant-failure.png',fullPage:false});
 await restore();await page.locator('#tenant-detail').getByRole('button',{name:'确定',exact:true}).click();
 const tenantId=await page.evaluate(n=>CloudCallData.tenants.find(t=>t.name===n)?.tenantId,name);
 check('恢复后只创建一个租户',!!tenantId&&await page.evaluate(n=>CloudCallData.tenants.filter(t=>t.name===n).length===1,name));
 await page.reload();
 check('新增租户刷新保留',await page.evaluate(id=>CloudCallData.tenants.some(t=>t.tenantId===id),tenantId));
 await page.evaluate(id=>{RouteRuntime.openPrimary('tenants');AccountTenantForms.openTenant(id)},tenantId);
 await page.locator('#tenantName').fill(name+'改');const editBefore=await snapshot();await inject();
 await page.locator('#tenant-detail').getByRole('button',{name:'确定',exact:true}).click();
 check('编辑租户失败原配置未变化',(await snapshot())===editBefore);
 check('编辑租户失败保留修改内容',await page.locator('#tenantName').inputValue()===name+'改');
 await restore();await page.locator('#tenant-detail').getByRole('button',{name:'确定',exact:true}).click();await page.reload();
 check('编辑租户重试后刷新一致',await page.evaluate(({id,n})=>CloudCallData.tenants.find(t=>t.tenantId===id)?.name===n,{id:tenantId,n:name+'改'}));
 await page.evaluate(()=>{RouteRuntime.openPrimary('accounts');AccountTenantForms.openAccount('TEN-NISSAN-HQ')});
 const username='rg14.'+Date.now();
 await page.locator('#newAccountUsername').fill(username);await page.locator('#newAccountNickname').fill('回归账号');await page.locator('#memberMobile').fill('13800009976');await page.locator('#memberMobile').blur();await page.locator('#explicitCreate').check();
 const accountBefore=await snapshot();await inject();await page.locator('#member-add').getByRole('button',{name:'确定',exact:true}).click();
 check('新增账号失败不留下账号或成员',(await snapshot())===accountBefore);
 check('新增账号失败保留完整输入',await page.locator('#newAccountUsername').inputValue()===username&&await page.locator('#explicitCreate').isChecked()&&await page.locator('#memberTenantError').innerText().then(t=>t.includes('保存失败')));
 await restore();await page.locator('#member-add').getByRole('button',{name:'确定',exact:true}).click();await page.reload();
 const ids=await page.evaluate(u=>{const a=CloudCallData.accounts.find(a=>a.loginUsername===u),m=CloudCallData.memberships.find(m=>m.accountId===a?.accountId&&m.tenantId==='TEN-NISSAN-HQ');return {accountId:a?.accountId,memberId:m?.membershipId}},username);
 check('账号重试成功且刷新不重复',!!ids.accountId&&!!ids.memberId&&await page.evaluate(u=>CloudCallData.accounts.filter(a=>a.loginUsername===u).length===1,username));
 await page.evaluate(id=>{RouteRuntime.openPrimary('accounts');Pages['account-tenant'].editMember(id)},ids.memberId);
 await page.locator('#editAccountNickname').fill('回归账号已修改');const memberBefore=await snapshot();await inject();await page.locator('#member-edit').getByRole('button',{name:'确定',exact:true}).click();
 check('成员编辑失败不改共享状态',(await snapshot())===memberBefore);
 check('成员编辑失败保留输入',await page.locator('#editAccountNickname').inputValue()==='回归账号已修改');
 await restore();await page.locator('#member-edit').getByRole('button',{name:'确定',exact:true}).click();await page.reload();
 check('成员编辑重试刷新保持',await page.evaluate(id=>CloudCallData.accounts.find(a=>a.accountId===id)?.nickname==='回归账号已修改',ids.accountId));
 const toggleBefore=await snapshot();await inject();await page.evaluate(id=>Pages['account-tenant'].toggleMember(id),ids.memberId);
 check('成员启停保存失败不改变状态',(await snapshot())===toggleBefore);
 await restore();await page.evaluate(id=>Pages['account-tenant'].toggleMember(id),ids.memberId);await page.reload();
 check('成员启停重试仅停用当前成员',await page.evaluate(ids=>CloudCallData.memberships.find(m=>m.membershipId===ids.memberId)?.status==='停用'&&CloudCallData.accounts.find(a=>a.accountId===ids.accountId)?.status==='启用',ids));
 await page.evaluate(id=>{RouteRuntime.openPrimary('tenants');Pages['account-tenant'].confirmToggleTenant(id)},tenantId);
 const tenantToggleBefore=await snapshot();await inject();await page.locator('#tenant-status-confirm').getByRole('button',{name:'停用',exact:true}).click();
 check('租户启停保存失败不改变状态',(await snapshot())===tenantToggleBefore);
 await restore();await page.reload();
 check('失败后的页面刷新仍一致',await page.evaluate(id=>CloudCallData.tenants.find(t=>t.tenantId===id)?.status==='启用',tenantId));
 check('无未捕获脚本错误',result.errors.length===0,result.errors);check('无资源加载失败',result.bad.length===0,result.bad);
 return result;
}
